    faq: {"title": "Frequently asked questions", "subtitle": "Have questions about Serenzer? You'll likely find your answer here.", "betaIntro": "Serenzer is currently in beta. This means some errors or inaccuracies may still occur: we're fixing them continuously, and your feedback helps us improve the experience.", "cats": [{"title": "Discovery & overview", "items": [{"q": "What is Serenzer?", "a": "Serenzer is a personal assistant that helps you organize your ideas, structure your Organisations and keep your information accessible, in a space designed to respect your pace."}, {"q": "Who is Serenzer for?", "a": "For anyone who wants to structure their daily life, Organisations or ideas, without complexity or pressure. Serenzer is not accessible to minors."}, {"q": "What devices can I use Serenzer on?", "a": "Serenzer can be used on smartphone, tablet or computer."}, {"q": "Is Serenzer available in my language?", "a": "Serenzer is available in 19 languages, with support for right-to-left languages."}]}, {"title": "Using the app", "items": [{"q": "How do I create my account?", "a": "You can create your account in a few simple steps from the home screen, following the guided setup.", "linkLabel": "Create my account", "linkHref": "https://apps.serenzer.com"}, {"q": "How does the assistant work?", "a": "Serenzer works in two ways: in conversation, where the assistant helps you organize and structure your ideas, or directly through its tools (calendar, challenges, rituals, Organisations)."}, {"q": "Can I pick up a conversation where I left off?", "a": "Yes, Serenzer remembers your discussions so you can naturally pick up where you left off."}, {"q": "How do I create a Challenge or an Organisation?", "a": "From the home screen, you can create a new Challenge or manage your Organisations according to your goals."}, {"q": "Is my information kept secure?", "a": "At Serenzer, we prioritize keeping your data protected and never selling it. It may be processed by technical services strictly necessary for Serenzer's operation, in compliance with applicable regulations. For more details, you can consult our privacy policy."}]}, {"title": "Subscriptions & pricing", "items": [{"q": "Is Serenzer free?", "a": "A free version gives you access to unlimited chat. Two paid subscription plans offer extended features."}, {"q": "What plans are available?", "a": "Several plans are offered, suited to different needs."}, {"q": "Can I change my plan or cancel my subscription at any time?", "a": "Yes, you can adjust or cancel your plan from your account settings, at any time. Cancellation takes effect at the end of the current period."}, {"q": "Is there a commitment?", "a": "No, no commitment is required; you're free to continue or stop whenever you like. As long as you don't delete your account, you can even come back later: Serenzer will remember you."}, {"q": "Is there a discount for an annual commitment?", "a": "Yes, a preferential rate is offered for an annual commitment. Check our pricing page for details.", "linkLabel": "See the pricing page", "linkHref": "pricing.html"}]}, {"title": "Still have doubts? These answers may help", "items": [{"q": "How is Serenzer different from a simple chatbot?", "a": "Unlike a classic chatbot that answers isolated questions, Serenzer is a genuine tool for structuring your ideas and Organisations. It keeps the context of your exchanges to support you over time, remembers your goals and helps you move forward, rather than simply chatting."}, {"q": "Is my data used to train the AI?", "a": "No, your exchanges remain tied to your personal use; consult our privacy policy for precise details on data processing."}, {"q": "Why pay for something I could do myself?", "a": "Serenzer saves you time by centralizing your ideas and Organisations in one clear space, without scattering across multiple tools."}, {"q": "Can the assistant make mistakes?", "a": "Like any AI assistant, inaccuracies remain possible; you always validate proposed actions before they are saved."}, {"q": "Isn't this just another productivity tool?", "a": "Serenzer stands out through its measured approach: no points to earn, no guilt-tripping, no pushy notifications, a space that adapts to your pace rather than the other way around."}, {"q": "Can I trust an AI assistant with my personal Organisations?", "a": "You stay in control of what you share and of every proposed action; nothing is done without your validation."}]}, {"title": "Support & common issues", "items": [{"q": "I got an error message, what should I do?", "a": "Try the action again; if the problem persists, contact our support describing the step involved."}, {"q": "My changes aren't saving, why?", "a": "Check your connection and that the action was validated. If the issue continues, report it to our team."}, {"q": "I'm not receiving Serenzer's emails.", "a": "Check your spam folder as well as the \"Promotions\" tab of your mailbox, then contact support if the problem persists."}, {"q": "How do I contact support?", "a": "You can write to us directly from your account; we'll get back to you as soon as possible."}, {"q": "How do I delete my account?", "a": "This option is available from your account. Deletion is permanent: your data is erased and, even if you resubscribe, you won't recover your history or where you left off."}]}]}
