    faq: {"title": "Ofte stillede spørgsmål", "subtitle": "Har du spørgsmål om Serenzer? Her finder du sikkert dit svar.", "betaIntro": "Serenzer er i øjeblikket i betaversion. Det betyder, at der stadig kan forekomme fejl eller unøjagtigheder: vi retter dem løbende, og din feedback hjælper os med at forbedre oplevelsen.", "cats": [{"title": "Opdagelse & præsentation", "items": [{"q": "Hvad er Serenzer?", "a": "Serenzer er en personlig assistent, der hjælper dig med at organisere dine idéer, strukturere dine Organisationer og holde dine oplysninger tilgængelige, i et rum designet til at respektere dit tempo."}, {"q": "Hvem henvender Serenzer sig til?", "a": "Til alle, der ønsker at strukturere deres hverdag, deres Organisationer eller deres idéer, uden kompleksitet eller pres. Serenzer er ikke tilgængelig for mindreårige."}, {"q": "Hvilke enheder kan jeg bruge Serenzer på?", "a": "Serenzer kan bruges på smartphone, tablet eller computer."}, {"q": "Er Serenzer tilgængelig på mit sprog?", "a": "Serenzer er tilgængelig på 19 sprog, med understøttelse af sprog, der skrives fra højre mod venstre."}]}, {"title": "Brug af appen", "items": [{"q": "Hvordan opretter jeg min konto?", "a": "Du kan oprette din konto i få enkle trin fra startskærmen ved at følge den guidede proces.", "linkLabel": "Opret min konto", "linkHref": "https://apps.serenzer.com"}, {"q": "Hvordan fungerer assistenten?", "a": "Serenzer fungerer på to måder: i samtale, hvor assistenten hjælper dig med at organisere og strukturere dine idéer, eller direkte via værktøjerne (kalender, challenges, ritualer, Organisationer)."}, {"q": "Kan jeg fortsætte en samtale, hvor jeg slap?", "a": "Ja, Serenzer husker dine samtaler, så du naturligt kan fortsætte, hvor du slap."}, {"q": "Hvordan opretter jeg et Challenge eller en Organisation?", "a": "Fra startskærmen kan du oprette et nyt Challenge eller administrere dine Organisationer ud fra dine mål."}, {"q": "Bliver mine oplysninger opbevaret sikkert?", "a": "Hos Serenzer lægger vi stor vægt på, at dine data forbliver beskyttet og aldrig sælges. De kan behandles af tekniske tjenester, der er strengt nødvendige for Serenzers drift, i overensstemmelse med gældende lovgivning. Se vores privatlivspolitik for flere detaljer."}]}, {"title": "Abonnementer & priser", "items": [{"q": "Er Serenzer gratis?", "a": "En gratis version giver adgang til ubegrænset chat. To betalte abonnementer tilbyder udvidede funktioner."}, {"q": "Hvilke abonnementer er tilgængelige?", "a": "Der tilbydes flere abonnementer, tilpasset forskellige behov."}, {"q": "Kan jeg ændre mit abonnement eller opsige det når som helst?", "a": "Ja, du kan justere eller opsige dit abonnement fra dine kontoindstillinger, når som helst. Opsigelsen træder i kraft ved udgangen af den igangværende periode."}, {"q": "Er der en binding?", "a": "Nej, der kræves ingen binding; du er fri til at fortsætte eller stoppe, når du vil. Så længe du ikke sletter din konto, kan du endda vende tilbage senere: Serenzer vil huske dig."}, {"q": "Er der rabat ved en årlig binding?", "a": "Ja, der tilbydes en fordelagtig pris ved en årlig binding. Se vores prisside for detaljer.", "linkLabel": "Se prisside", "linkHref": "pricing.html"}]}, {"title": "Stadig i tvivl? Disse svar kan hjælpe dig", "items": [{"q": "Hvordan adskiller Serenzer sig fra en simpel chatbot?", "a": "I modsætning til en klassisk chatbot, der besvarer isolerede spørgsmål, er Serenzer et ægte værktøj til at strukturere dine idéer og Organisationer. Det bevarer konteksten af dine samtaler for at følge dig over tid, husker dine mål og hjælper dig fremad, i stedet for blot at chatte."}, {"q": "Bruges mine data til at træne AI'en?", "a": "Nej, dine samtaler forbliver knyttet til din personlige brug; se vores privatlivspolitik for præcise detaljer om databehandlingen."}, {"q": "Hvorfor betale for noget, jeg selv kunne gøre?", "a": "Serenzer sparer dig tid ved at samle dine idéer og Organisationer ét overskueligt sted, uden spredning på flere værktøjer."}, {"q": "Kan assistenten tage fejl?", "a": "Som enhver AI-assistent kan der forekomme unøjagtigheder; du godkender altid foreslåede handlinger, før de gemmes."}, {"q": "Er det ikke bare endnu et produktivitetsværktøj?", "a": "Serenzer skiller sig ud ved sin afmålte tilgang: ingen point at optjene, ingen skyldfølelse, ingen påtrængende notifikationer, et rum der tilpasser sig dit tempo og ikke omvendt."}, {"q": "Kan jeg betro en AI-assistent mine personlige Organisationer?", "a": "Du bevarer kontrollen over, hvad du deler, og over hver foreslået handling; intet sker uden din godkendelse."}]}, {"title": "Support & almindelige problemer", "items": [{"q": "Jeg fik en fejlmeddelelse, hvad gør jeg?", "a": "Prøv handlingen igen; hvis problemet fortsætter, kontakt vores support og beskriv det pågældende trin."}, {"q": "Mine ændringer bliver ikke gemt, hvorfor?", "a": "Tjek din forbindelse, og at handlingen er blevet godkendt. Fortsætter problemet, så meld det til vores team."}, {"q": "Jeg modtager ikke Serenzers e-mails.", "a": "Tjek din uønsket post-mappe samt fanen \"Kampagner\" i din indbakke, og kontakt derefter support, hvis problemet fortsætter."}, {"q": "Hvordan kontakter jeg support?", "a": "Du kan skrive direkte til os fra din konto; vi svarer dig hurtigst muligt."}, {"q": "Hvordan sletter jeg min konto?", "a": "Denne mulighed er tilgængelig fra din konto. Sletningen er endelig: dine data slettes, og selv ved fornyet abonnement finder du hverken din historik eller det sted, du var nået til."}]}]}
