    rit_desc: "يساعدك Serenzer على إنشاء طقوس دائمة وتحديات مؤقتة، باقتراحات مصممة وفق ما شاركته بالفعل.",
    rit_bullets: ["تقدم بوتيرتك الخاصة", "اقتراحات ذكاء اصطناعي مخصصة", "أهداف مؤقتة أو دائمة", "يمكن أن يتحول التحدي إلى طقس"],
    rit_card_title: "طقوس اليوم",
