    rit_item4_badge: "تحدي · اليوم 3/7",
    contact_form_required: "يرجى ملء جميع الحقول.",
    contact_form_email: "عنوان البريد الإلكتروني غير صالح.",
    contact_form_toolong: "أحد الحقول يتجاوز الطول المسموح به.",
    team_meta_title: "الفريق · Serenzer",
    nav_team: "من نحن",
    nav_home: "الرئيسية",
    nav_about: "الميزات",
    team_eyebrow: "من نحن",
    team_title: "مشروع وُلد حول مائدة عائلية، لا في مرآب في وادي السيليكون.",
    team_lead1: "<strong>تأسست Serenzer Ltd على يد عائلة Jore بأكملها</strong>: أبوان وأربعة أبناء وستة مؤسسين مشاركين. لا جولات تمويل، لا حاضنات أعمال. كل شيء انطلق من عشاء عائلي، حين أدرك الجميع أنهم يرزحون تحت وطأة الأشياء الصغيرة ذاتها في الحياة اليومية: المواعيد، والإجراءات، وتنظيم انتقال سكني، والتحضير لمقابلة عمل، وعدم نسيان المقربين.",
    team_rule: "«إن أضرّ المشروع بعائلتنا، أوقفنا كل شيء.»",
    team_rule_attr: "القاعدة الذهبية لعائلة Jore، وُضعت منذ اليوم الأول.",
    team_lead2: "كانت الفكرة بسيطة: ماذا لو كان لدينا شخص نتحدث إليه لنجد طريقنا؟ لا خبير، لا مرشد، مجرد مساعدة يومية في متناول اليد عبر محادثة عادية. حول تلك الطاولة كان ثمة ما يكفي لبنائها: معالجة نفسية متخصصة في التحليل التبادلي، ورجل أعمال أمضى عشرين عامًا في بناء البرمجيات وعاد إلى الكود ليكتب عقل المساعد، وأربعة أبناء يتقنون الهاتف المحمول والتسويق والأكواد الثقافية لأربع قارات.",
    team_grid_eyebrow: "الفريق",
    team_grid_title: "الوجوه خلف Serenzer",
    team_grid_subtitle: "ستة مؤسسين مشاركين، وكلب، وقناعة مشتركة: لا يمكن التظاهر باللطف حين تعيشه كل يوم.",
    m_raphael_role: "CTO &amp; المطوّر الرئيسي",
    m_raphael_line: "عالم نفس ورجل أعمال، يكتب اليوم عقل المساعد.",
    m_raphael_bio: "تلقّى Raphaël تدريبه في علم النفس ثم في التسويق في ESSEC، وعمل خمس سنوات كعالم نفس مع الشباب قبل أن يتحول نحو التكنولوجيا بتأسيس شركة البرمجيات Splio، التي انتشرت من فرنسا إلى البرازيل مرورًا بالصين. بعد عشرين عامًا، عاد إلى الكود، وتعلّم تقنيات الذكاء الاصطناعي الحديثة وأصبح المطوّر الرئيسي لـ Serenzer. إنه من يكتب، سطرًا بسطر، عقل المساعد. وهو أيضًا منتج موسيقي.",
    m_delphine_role: "ضامنة اللطف",
    m_delphine_line: "متخصصة في التحليل التبادلي، تدرّب المساعد كل يوم وتسهر على أخلاقياته.",
    m_delphine_bio: "تلقّت Delphine تدريبها في التحليل التبادلي وأدارت عيادة للعلاج النفسي لمدة عشر سنوات. أمٌّ لأربعة أبناء، تشغل اليوم دورًا نادرًا في عالم التكنولوجيا. كل يوم تدرّب المساعد: عبر سلسلة من حسابات الاختبار التي أعدّتها بنفسها، تسائله دون توقف، وتختبر إجاباته وتضبط نبرته. شاغلها الدائم هو الأخلاقيات، أخلاقيات الشركة وأخلاقيات Serenzer بوصفه روبوت محادثة. إنها من تطرح السؤال الوحيد الذي يهم حقًا: هل يساعد الناس فعلًا؟ هنا، اللطف ليس حجة تسويقية، بل رقابة جودة يومية.",
    m_samuel_role: "قائد الأوركسترا",
    m_samuel_line: "يرسم التوجه، ويحكّم، ويتحقق من وصول الرسالة في 19 لغة وتكيّفاتها الإقليمية.",
    m_samuel_bio: "الابن الأكبر، تلقّى تدريبه في إدارة المشاريع في كندا، يدير Samuel الاجتماعات ويرسم التوجه ويجمع ملاحظات المستخدمين مباشرة. قادر على الإمساك بالرؤية الشاملة دون أن يفوته أي تفصيل، إنه من يهيكل ويحكّم. حين تخاطب Serenzer 19 لغة وتكيّفاتها الإقليمية، هو من يتحقق من وصول الرسالة.",
    m_maya_role: "Storyteller",
    m_maya_line: "تصوغ رواية العلامة التجارية وكتابة المحتوى.",
    m_maya_bio: "الابنة الثانية، نشأت بين فرنسا والولايات المتحدة، ومرّت بكتابة السيناريو ثم EM Lyon. التسويق من الجيل الجديد والـ storytelling ووسائل التواصل الاجتماعي هي ميدانها. فنانة ومنظّمة، صارمة وحساسة للهواية، تصوغ رواية العلامة التجارية والتجربة السردية للمنتج.",
    m_noe_role: "Mobile &amp; QA",
    m_noe_line: "يقود تجربة الهاتف المحمول ويتتبع العيوب، بنظرة مستخدم في العشرين من عمره.",
    m_noe_bio: "الابن الثالث، تلقّى تعليمه بين فرنسا والولايات المتحدة والمغرب. مولع بالتقنية وقادر على التكيّف في كل مكان، يتولى تجربة الهاتف المحمول ومراقبة الجودة: يختبر ويتتبع العيوب ويضع نفسه في مكان المستخدم، بنظرة شاب في العشرين عاش على ثلاث قارات.",
    m_lou_role: "صوت الجيل الجديد",
    m_lou_line: "الأصغر: النظرة الصريحة بلا فلتر للجيل الذي ينشأ مع الذكاء الاصطناعي.",
    m_lou_bio: "الابنة الصغرى، ثنائية الثقافة فرنسية-أمريكية، تتقن اللغتين بشكل تام. منجذبة إلى الموسيقى والتقنيات الجديدة، تجلب ما لا تستطيع أي دراسة سوق توفيره: النظرة الفورية والصريحة بلا فلتر للجيل الذي ينشأ مع الذكاء الاصطناعي.",
