    faq: {"title": "الأسئلة الشائعة", "subtitle": "هل لديك أسئلة حول Serenzer؟ ستجد إجابتك على الأرجح هنا.", "betaIntro": "يوجد Serenzer حاليًا في نسخة تجريبية (بيتا). هذا يعني أنه قد تحدث بعض الأخطاء أو عدم الدقة: نقوم بتصحيحها باستمرار، وتساعدنا ملاحظاتكم على تحسين التجربة.", "cats": [{"title": "الاكتشاف والتقديم", "items": [{"q": "ما هو Serenzer؟", "a": "Serenzer هو مساعد شخصي يساعدك على تنظيم أفكارك، وهيكلة منظماتك، والحفاظ على معلوماتك في متناول يدك، ضمن مساحة مصممة لاحترام وتيرتك."}, {"q": "لمن يوجَّه Serenzer؟", "a": "لكل شخص يرغب في تنظيم حياته اليومية أو منظماته أو أفكاره، دون تعقيد أو ضغط. لا يمكن للقاصرين استخدام Serenzer."}, {"q": "على أي الأجهزة يمكنني استخدام Serenzer؟", "a": "يمكن استخدام Serenzer على الهاتف الذكي أو الجهاز اللوحي أو الكمبيوتر."}, {"q": "هل Serenzer متاح بلغتي؟", "a": "Serenzer متاح بـ 19 لغة، مع دعم اللغات التي تُكتب من اليمين إلى اليسار."}]}, {"title": "استخدام التطبيق", "items": [{"q": "كيف أنشئ حسابي؟", "a": "يمكنك إنشاء حسابك في خطوات بسيطة من الشاشة الرئيسية، باتباع المسار الموجَّه.", "linkLabel": "إنشاء حسابي", "linkHref": "https://apps.serenzer.com"}, {"q": "كيف يعمل المساعد؟", "a": "يعمل Serenzer بطريقتين: عبر المحادثة، حيث يساعدك المساعد على تنظيم وهيكلة أفكارك، أو مباشرة عبر أدواته (التقويم، التحديات، الطقوس، المنظمات)."}, {"q": "هل يمكنني متابعة محادثة من حيث توقفت؟", "a": "نعم، يتذكر Serenzer محادثاتك حتى تتمكن من المتابعة بشكل طبيعي من حيث توقفت."}, {"q": "كيف أنشئ Challenge أو منظمة؟", "a": "من الشاشة الرئيسية، يمكنك إنشاء Challenge جديد أو إدارة منظماتك وفقًا لأهدافك."}, {"q": "هل يتم الحفاظ على معلوماتي بأمان؟", "a": "في Serenzer، نحرص أشد الحرص على أن تبقى بياناتك محمية وألا تُباع أبدًا. يمكن معالجتها من قبل خدمات تقنية ضرورية بشكل صارم لتشغيل Serenzer، وفقًا للتنظيمات المعمول بها. لمزيد من التفاصيل، يمكنك الاطلاع على سياسة الخصوصية لدينا."}]}, {"title": "الاشتراكات والأسعار", "items": [{"q": "هل Serenzer مجاني؟", "a": "تمنحك النسخة المجانية إمكانية الوصول إلى محادثة غير محدودة. يوفر خياران مدفوعان ميزات موسّعة."}, {"q": "ما هي الخطط المتاحة؟", "a": "تُقترح عدة خطط تناسب استخدامات مختلفة."}, {"q": "هل يمكنني تغيير خطتي أو إلغاء اشتراكي في أي وقت؟", "a": "نعم، يمكنك تعديل أو إلغاء خطتك من إعدادات حسابك، في أي وقت. يسري الإلغاء في نهاية الفترة الجارية."}, {"q": "هل هناك التزام؟", "a": "لا، لا يُطلب أي التزام؛ تبقى حرًا في المتابعة أو التوقف متى شئت. وطالما لم تحذف حسابك، يمكنك حتى العودة لاحقًا: سيتذكرك Serenzer."}, {"q": "هل يوجد خصم للالتزام السنوي؟", "a": "نعم، يُقدَّم سعر تفضيلي للالتزام السنوي. اطّلع على صفحة الأسعار للتفاصيل.", "linkLabel": "عرض صفحة الأسعار", "linkHref": "pricing.html"}]}, {"title": "لا تزال لديك شكوك؟ قد تساعدك هذه الإجابات", "items": [{"q": "بماذا يختلف Serenzer عن chatbot بسيط؟", "a": "على عكس chatbot تقليدي يجيب عن أسئلة منعزلة، يُعد Serenzer أداة حقيقية لهيكلة أفكارك ومنظماتك. فهو يحافظ على سياق محادثاتك لمرافقتك على المدى الطويل، ويتذكر أهدافك، ويساعدك على التقدم بدلًا من مجرد الدردشة."}, {"q": "هل تُستخدم بياناتي لتدريب الذكاء الاصطناعي؟", "a": "لا، تبقى محادثاتك مرتبطة باستخدامك الشخصي فقط؛ اطّلع على سياسة الخصوصية لدينا للاطلاع على تفاصيل دقيقة حول معالجة البيانات."}, {"q": "لماذا أدفع مقابل شيء يمكنني القيام به بنفسي؟", "a": "يوفر لك Serenzer الوقت من خلال تجميع أفكارك ومنظماتك في مساحة واضحة واحدة، دون تشتت بين أدوات متعددة."}, {"q": "هل يمكن للمساعد أن يخطئ؟", "a": "مثل أي مساعد ذكاء اصطناعي، تبقى بعض عدم الدقة ممكنة؛ أنت تُصادق دائمًا على الإجراءات المقترحة قبل تسجيلها."}, {"q": "أليست هذه مجرد أداة إنتاجية أخرى؟", "a": "يتميّز Serenzer بنهجه المتوازن: لا نقاط لتكسبها، لا شعور بالذنب، لا إشعارات ملحّة، مساحة تتكيف مع وتيرتك وليس العكس."}, {"q": "هل يمكنني الوثوق بمساعد ذكاء اصطناعي لإدارة منظماتي الشخصية؟", "a": "تحتفظ بالسيطرة على ما تشاركه وعلى كل إجراء مقترح؛ لا يُنفَّذ شيء دون موافقتك."}]}, {"title": "الدعم والمشاكل الشائعة", "items": [{"q": "ظهرت لي رسالة خطأ، ماذا أفعل؟", "a": "أعد محاولة الإجراء؛ إذا استمرت المشكلة، تواصل مع الدعم مع وصف الخطوة المعنية."}, {"q": "لا يتم حفظ تعديلاتي، لماذا؟", "a": "تحقق من اتصالك ومن أن الإجراء قد تمت المصادقة عليه. إذا استمرت المشكلة، أبلغ فريقنا."}, {"q": "لا أستلم رسائل البريد الإلكتروني من Serenzer.", "a": "تحقق من مجلد البريد غير المرغوب فيه وكذلك من علامة تبويب «العروض» في صندوق بريدك، ثم تواصل مع الدعم إذا استمرت المشكلة."}, {"q": "كيف أتواصل مع الدعم؟", "a": "يمكنك مراسلتنا مباشرة من حسابك؛ سنرد عليك في أقرب وقت ممكن."}, {"q": "كيف أحذف حسابي؟", "a": "هذا الخيار متاح من حسابك. الحذف نهائي: تُمحى بياناتك، وحتى في حال إعادة الاشتراك، لن تسترجع سجلك أو النقطة التي توقفت عندها."}]}]}
